/* @lc app=leetcode id=3606 lang=kotlin */ class Solution { fun validateCoupons(code: Array<String>, businessLine: Array<String>, isActive: BooleanArray): List<String> = listOf("electronics", "grocery", "pharmacy", "restaurant").let { order -> code.indices.filter { i -> code[i].isNotEmpty() && code[i].all { c -> c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9' || c == '_' } && businessLine[i] in order && isActive[i] }.sortedWith(compareBy<Int>({ order.indexOf(businessLine[it]) }, { code[it] })).map { code[it] } } }